def solve(g):
    H,W=len(g),len(g[0])
    objs=objects(g)
    two_row = next(r for r in range(H) if all(x==2 for x in g[r]))
    d = -1 if two_row==0 else 1
    grid=[[0]*W for _ in range(H)]
    grid[two_row]=[2]*W
    pos=[list(c) for c in objs]
    moved=True
    while moved:
        moved=False
        order=sorted(range(len(pos)), key=lambda i: max(r for r,c in pos[i]))
        for i in order:
            newp=[(r+d,c) for r,c in pos[i]]
            occ=set()
            for j,p in enumerate(pos):
                if j!=i: occ.update((r,c) for r,c in p)
            if all(0<=r<H and grid[r][c]!=2 and (r,c) not in occ for r,c in newp):
                pos[i]=newp; moved=True
    for p,cells in zip(pos,objs):
        col=g[cells[0][0]][cells[0][1]]
        for r,c in p: grid[r][c]=col
    return grid

